function indexOf(lang: Lang): number {
  const index = languageCodes.indexOf(lang)
  return index < 0 ? 0 : index
}

export function regionHistory(lang: Lang): string {
  return region[lang]
}

export function placeHistory(name: string, town: string, lang: Lang): string | null {
  if (name === 'Plaza de Bolívar' && town !== 'Salento') return null
  const parts = facts[name]
  if (!parts || parts.length !== languageCodes.length) return null
  const body = parts[indexOf(lang)]
  const year = years[name]
  if (!year) return body
  return `${yearLine[indexOf(lang)](name, year)} ${body}`
}

export function hasHistory(name: string, town: string): boolean {
  if (name === 'Plaza de Bolívar' && town !== 'Salento') return false
  const parts = facts[name]
  return Boolean(parts && parts.length === languageCodes.length)
}
